insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values
('70000000-0000-4000-8000-000093200511','40000000-0000-4000-8000-000000930051','Dados: $\overline A+\overline B$','Qual expressão equivale a $\overline{A\cdot B}$?',1),
('70000000-0000-4000-8000-000093200512','40000000-0000-4000-8000-000000930051','Princípio: $\overline A+\overline B$','A lei de De Morgan troca AND por OR ao negar cada operando.',2),
('70000000-0000-4000-8000-000093200513','40000000-0000-4000-8000-000000930051','Estratégia: $\overline A+\overline B$','Aplique a negação a toda a conjunção.',3),
('70000000-0000-4000-8000-000093200514','40000000-0000-4000-8000-000000930051','Verificação: $\overline A+\overline B$','A tabela-verdade confirma igualdade em todos os casos.',4),
('70000000-0000-4000-8000-000093200515','40000000-0000-4000-8000-000000930051','Conclusão: $\overline A+\overline B$','A alternativa correta é “$\overline A+\overline B$”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093200521','40000000-0000-4000-8000-000000930052','Dados: $A$','Simplifique $A\cdot B+A\cdot\overline B$.',1),
('70000000-0000-4000-8000-000093200522','40000000-0000-4000-8000-000000930052','Princípio: $A$','Fatoração produz $A(B+\overline B)$.',2),
('70000000-0000-4000-8000-000093200523','40000000-0000-4000-8000-000000930052','Estratégia: $A$','Use complementaridade dentro dos parênteses.',3),
('70000000-0000-4000-8000-000093200524','40000000-0000-4000-8000-000000930052','Verificação: $A$','$B+\overline B=1$, restando $A$.',4),
('70000000-0000-4000-8000-000093200525','40000000-0000-4000-8000-000000930052','Conclusão: $A$','A alternativa correta é “$A$”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093200531','40000000-0000-4000-8000-000000930053','Dados: Quando as entradas são diferentes.','Quando uma porta XOR de duas entradas produz $1$?',1),
('70000000-0000-4000-8000-000093200532','40000000-0000-4000-8000-000000930053','Princípio: Quando as entradas são diferentes.','XOR representa desigualdade entre dois bits.',2),
('70000000-0000-4000-8000-000093200533','40000000-0000-4000-8000-000000930053','Estratégia: Quando as entradas são diferentes.','Compare os quatro pares possíveis de entrada.',3),
('70000000-0000-4000-8000-000093200534','40000000-0000-4000-8000-000000930053','Verificação: Quando as entradas são diferentes.','Apenas $01$ e $10$ ativam a saída.',4),
('70000000-0000-4000-8000-000093200535','40000000-0000-4000-8000-000000930053','Conclusão: Quando as entradas são diferentes.','A alternativa correta é “Quando as entradas são diferentes.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093200541','40000000-0000-4000-8000-000000930054','Dados: Porque combinações de NAND implementam NOT, AND e OR.','Por que NAND é considerada porta universal?',1),
('70000000-0000-4000-8000-000093200542','40000000-0000-4000-8000-000000930054','Princípio: Porque combinações de NAND implementam NOT, AND e OR.','Funcionalidade universal vem de poder construir um conjunto funcionalmente completo.',2),
('70000000-0000-4000-8000-000093200543','40000000-0000-4000-8000-000000930054','Estratégia: Porque combinações de NAND implementam NOT, AND e OR.','Comece construindo NOT com entradas NAND unidas.',3),
('70000000-0000-4000-8000-000093200544','40000000-0000-4000-8000-000000930054','Verificação: Porque combinações de NAND implementam NOT, AND e OR.','Depois de NOT, De Morgan permite formar AND e OR.',4),
('70000000-0000-4000-8000-000093200545','40000000-0000-4000-8000-000000930054','Conclusão: Porque combinações de NAND implementam NOT, AND e OR.','A alternativa correta é “Porque combinações de NAND implementam NOT, AND e OR.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093200551','40000000-0000-4000-8000-000000930055','Dados: São logicamente equivalentes.','Dois circuitos têm expressões diferentes, mas mesma saída para todas as entradas. Qual conclusão é válida?',1),
('70000000-0000-4000-8000-000093200552','40000000-0000-4000-8000-000000930055','Princípio: São logicamente equivalentes.','Equivalência lógica depende da função, não da implementação física.',2),
('70000000-0000-4000-8000-000093200553','40000000-0000-4000-8000-000000930055','Estratégia: São logicamente equivalentes.','Compare tabelas-verdade ou simplifique as expressões.',3),
('70000000-0000-4000-8000-000093200554','40000000-0000-4000-8000-000000930055','Verificação: São logicamente equivalentes.','Mesmo comportamento não garante custo ou atraso iguais.',4),
('70000000-0000-4000-8000-000093200555','40000000-0000-4000-8000-000000930055','Conclusão: São logicamente equivalentes.','A alternativa correta é “São logicamente equivalentes.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093200561','40000000-0000-4000-8000-000000930056','Dados: Encaminhar uma entre oito entradas para uma saída.','Qual é a função de um multiplexador $8:1$?',1),
('70000000-0000-4000-8000-000093200562','40000000-0000-4000-8000-000000930056','Princípio: Encaminhar uma entre oito entradas para uma saída.','Linhas de seleção escolhem qual entrada aparece na saída.',2),
('70000000-0000-4000-8000-000093200563','40000000-0000-4000-8000-000000930056','Estratégia: Encaminhar uma entre oito entradas para uma saída.','Observe se o bloco escolhe, expande ou armazena informação.',3),
('70000000-0000-4000-8000-000093200564','40000000-0000-4000-8000-000000930056','Verificação: Encaminhar uma entre oito entradas para uma saída.','Um MUX concentra várias fontes em um destino.',4),
('70000000-0000-4000-8000-000093200565','40000000-0000-4000-8000-000000930056','Conclusão: Encaminhar uma entre oito entradas para uma saída.','A alternativa correta é “Encaminhar uma entre oito entradas para uma saída.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093200571','40000000-0000-4000-8000-000000930057','Dados: $4$','Quantas linhas de seleção são necessárias para um multiplexador $16:1$?',1),
