('70000000-0000-4000-8000-000093200575','40000000-0000-4000-8000-000000930057','Conclusão: $4$','A alternativa correta é “$4$”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093200581','40000000-0000-4000-8000-000000930058','Dados: Soma $0$ e carry $1$.','Para entradas $A=1$ e $B=1$, quais são soma e carry de um meio somador?',1),
('70000000-0000-4000-8000-000093200582','40000000-0000-4000-8000-000000930058','Princípio: Soma $0$ e carry $1$.','Soma é XOR; carry é AND.',2),
('70000000-0000-4000-8000-000093200583','40000000-0000-4000-8000-000000930058','Estratégia: Soma $0$ e carry $1$.','Avalie as duas portas para o par $11$.',3),
('70000000-0000-4000-8000-000093200584','40000000-0000-4000-8000-000000930058','Verificação: Soma $0$ e carry $1$.','$1\oplus1=0$ e $1\cdot1=1$.',4),
('70000000-0000-4000-8000-000093200585','40000000-0000-4000-8000-000000930058','Conclusão: Soma $0$ e carry $1$.','A alternativa correta é “Soma $0$ e carry $1$.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093200591','40000000-0000-4000-8000-000000930059','Dados: Para somar também o transporte vindo da posição menos significativa.','Por que um somador completo precisa de entrada de carry?',1),
('70000000-0000-4000-8000-000093200592','40000000-0000-4000-8000-000000930059','Princípio: Para somar também o transporte vindo da posição menos significativa.','Em palavras multibit, cada coluna pode receber transporte da anterior.',2),
